import { APPLICATION_COLUMNS, getSql } from "@/lib/db";
import type { Application } from "@/lib/types";

// The fields a client may set. The id is always generated by the database.
export type ApplicationInput = Omit<Application, "id">;

// Every user-provided value goes in `params` ($1, $2, ...) and is sent
// separately from the SQL text, so it can never be read as SQL. The only text
// ever added to a query string is the constant column list.
async function query(
  text: string,
  params: unknown[] = [],
): Promise<Application[]> {
  const rows = await getSql().query(text, params);
  return rows as Application[];
}

// Oldest first: APP-001, APP-002, ... (length first, so APP-1000 sorts after
// APP-999). This is the same order the old in-memory array had.
export async function listApplications(): Promise<Application[]> {
  return query(
    `SELECT ${APPLICATION_COLUMNS} FROM applications ORDER BY length(id), id`,
  );
}

export async function getApplication(id: string): Promise<Application | null> {
  const rows = await query(
    `SELECT ${APPLICATION_COLUMNS} FROM applications WHERE id = $1`,
    [id],
  );
  return rows[0] ?? null;
}

// ONE database round trip. A single statement draws the next number from the
// sequence, formats it as APP-###, and inserts the row. The sequence is atomic
// across every server instance, so two creates can never get the same id, and
// a number is never reused (even after a delete or a restart).
//
// lpad() would cut a number longer than its width, so the width is never
// smaller than the number: APP-999 is followed by APP-1000, not APP-100.
// The explicit casts tell PostgreSQL the type of each parameter.
export async function createApplication(
  input: ApplicationInput,
): Promise<Application> {
  const rows = await query(
    `WITH next AS (SELECT nextval('application_number_seq') AS n)
     INSERT INTO applications (id, company, role, stage, applied_date)
     SELECT 'APP-' || lpad(n::text, greatest(3, length(n::text)), '0'),
            $1::text, $2::text, $3::text, $4::date
     FROM next
     RETURNING ${APPLICATION_COLUMNS}`,
    [input.company, input.role, input.stage, input.appliedDate],
  );
  if (!rows[0]) {
    throw new Error("The database did not return the created application.");
  }
  return rows[0];
}

// Returns the updated record, or null when the id does not exist (anymore).
// The id never changes.
export async function updateApplication(
  id: string,
  input: ApplicationInput,
): Promise<Application | null> {
  const rows = await query(
    `UPDATE applications
     SET company = $2, role = $3, stage = $4, applied_date = $5
     WHERE id = $1
     RETURNING ${APPLICATION_COLUMNS}`,
    [id, input.company, input.role, input.stage, input.appliedDate],
  );
  return rows[0] ?? null;
}

// Returns true when a record was deleted, false when the id did not exist.
export async function deleteApplication(id: string): Promise<boolean> {
  const rows = await getSql().query(
    `DELETE FROM applications WHERE id = $1 RETURNING id`,
    [id],
  );
  return rows.length > 0;
}
